import{o,c as a,a2 as r,k as t,e as s,F as c,B as n}from"./chunks/framework.BaXgE4DV.js";const l=JSON.parse('[{"id":"GRATO-18","html":"<h3 id=\\"badge-celebration\\" tabindex=\\"-1\\">배지 축하 카드와 다음 배지 <a class=\\"header-anchor\\" href=\\"#badge-celebration\\" aria-label=\\"Permalink to &quot;배지 축하 카드와 다음 배지 {#badge-celebration}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>배지를 얻으면 한 번, 조용한 축하 카드가 뜸: &quot;새 배지&quot;, 아이콘, 이름·설명, 호칭이 있으면 &quot;이름 옆에 이렇게 보여요&quot; 미리보기와 <strong>이름 옆에 붙이기</strong>, 보상 공감 이모지, 다음 배지, 공유하기·닫기. 약 1.2초 연출(고리·빛줄기·입자 한 번), 움직임 줄이기에서는 페이드만, 앱은 가벼운 진동 1회 → <a href=\\"/grato-docs/features/stats-badges#celebration\\">배지 축하</a></li>\\n<li>한꺼번에 여러 개를 받으면 &quot;그동안 모은 배지 n개&quot; 한 장으로. 호칭은 가장 최근 것 하나만 바로 붙이고, 나머지는 마이페이지에서 고름</li>\\n<li>글 쓰는 중이나 다른 창 위에서는 기다렸다가 띄우고, 저절로 사라지지 않음. 같은 배지는 다른 기기에서도 다시 뜨지 않음(<code>users.badgesSeenAt</code>), 업데이트 전에 가진 배지는 축하하지 않음 → <a href=\\"/grato-docs/decisions#adr-29\\">ADR-29</a></li>\\n<li>홈 기록 카드와 마이페이지 배지 카드에 &quot;다음 배지 · 보름의 마음까지 8일&quot; 한 줄과 작은 진행 막대. 축하 카드 끝에 &quot;오늘 쓴 감사 다시 보기&quot; → <a href=\\"/grato-docs/features/stats-badges#next-badge\\">다음 배지</a></li>\\n<li>규칙(<code>badgesSeenAt</code>)·함수(<code>userBadges.progress</code>) 먼저, 그다음 Hosting. 앱은 iOS 1.0.1 (5)부터 → <a href=\\"/grato-docs/operations/deploy#release-badge-celebration\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-21","html":"<h3 id=\\"release-streak-recovery\\" tabindex=\\"-1\\">쉼표의 날과 기록한 날 먼저 <a class=\\"header-anchor\\" href=\\"#release-streak-recovery\\" aria-label=\\"Permalink to &quot;쉼표의 날과 기록한 날 먼저 {#release-streak-recovery}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li><strong>쉼표의 날</strong>: 연속일이 끊긴 다음 날 하루 안에 쓰면 비운 하루를 쉼표의 날로 바꿔 연속일이 이어짐(연속 3일 이상, 한 달에 한 번, 서버가 판단). 홈에 &quot;어제는 바쁜 하루였나 봐요. 오늘 쓰면 n일 연속으로 이어져요&quot; → <a href=\\"/grato-docs/features/stats-badges#rest-day\\">쉼표의 날</a></li>\\n<li><strong>기록한 날 먼저</strong>: 홈 카드 제목이 &quot;기록한 날 n일&quot;(누적, 끊겨도 줄지 않음), 연속일은 3일째부터 작은 칩. 끊긴 연속일을 0으로 보여 주지 않고 &quot;바쁜 날도 있죠. 기록한 날은 그대로 남아 있어요&quot;. 마이페이지 숫자 칸에 <strong>기록한 날</strong> 추가, 캘린더 카드는 연속일이 끊기면 그 달 최장 연속</li>\\n<li><strong>연속일 숨기기</strong>(설정): 홈·마이페이지·위젯·공유 캘린더·이름 옆에서 연속일을 숨김 → <a href=\\"/grato-docs/features/stats-badges#hide-streak\\">연속일 숨기기</a></li>\\n<li>함수·규칙 배포 뒤 <code>backfillActiveDays</code> 필요(<code>userStats.activeDays</code>, <code>restDays</code>, <code>users.hideStreak</code> 추가) → <a href=\\"/grato-docs/operations/deploy#release-streak-recovery\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-22","html":"<h3 id=\\"daily-topic\\" tabindex=\\"-1\\">모두의 감사방 오늘의 주제 <a class=\\"header-anchor\\" href=\\"#daily-topic\\" aria-label=\\"Permalink to &quot;모두의 감사방 오늘의 주제 {#daily-topic}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>모두의 감사방 탭 맨 위에 <strong>오늘의 주제</strong>: 매일 07:00(한국 시간)에 운영자가 예약한 질문 하나와 &quot;오늘 n명이 답했어요&quot;(3명 미만이면 &quot;첫 답을 남겨 보세요&quot;), [답하기], &quot;오늘 주제 말고 자유롭게 써도 돼요&quot; → <a href=\\"/grato-docs/features/circles#daily-topic\\">오늘의 주제</a></li>\\n<li>답은 <strong>감사 글</strong>로 저장되어 기록한 날·배지에 그대로 쌓임. 기본은 나만 보기, 이 방을 미리 고르지 않음, 제목은 쓰지 않아도 됨. 고를 수 있는 Circle은 모두의 감사방뿐</li>\\n<li>주제 아래 답은 시간순(새 답이 위), 인기순 없음. 답하기 전에는 새 답 3개만 보이고, 나만 보기로 답해도 전부 열림. 다른 사람 답의 공감 숫자는 보이지 않음(내 답은 보임)</li>\\n<li>답한 글 위에 &quot;오늘의 주제: …&quot;(내 기록·글 화면·지난 답). 선정된 사용자 질문은 방에서 이름 없이 &quot;💡 Grato 사용자가 제안한 질문&quot;</li>\\n<li>관리자 › <strong>주제</strong> 탭: 날짜별 예약(92일 뒤까지), 출처(운영자·선정 질문·시즌), 결. 서버가 문구(5~80자, 링크·연락처·욕설, &quot;AI&quot;·&quot;인공지능&quot;)와 8주 안 같은 문구를 막음 → <a href=\\"/grato-docs/decisions#adr-31\\">ADR-31</a></li>\\n<li>함수(<code>manageDailyTopic</code>) + Firestore 규칙·인덱스 → Hosting 순서. 앱은 iOS 1.0.1 (5)부터. 모두의 감사방이 꺼져 있는 동안 사용자 화면 변화 없음 → <a href=\\"/grato-docs/operations/deploy#release-daily-topic\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-23","html":"<h3 id=\\"comment-reactions\\" tabindex=\\"-1\\">댓글에도 공감 <a class=\\"header-anchor\\" href=\\"#comment-reactions\\" aria-label=\\"Permalink to &quot;댓글에도 공감 {#comment-reactions}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>댓글 아래 작은 버튼으로 공감(❤️ 🙏 ✨ 🔥)을 남김. 숫자는 작게, 댓글은 그대로 오래된 순. 배지로 받는 보상 공감은 글에만 → <a href=\\"/grato-docs/features/gratitudes#comment-reactions\\">댓글 공감</a>, <a href=\\"/grato-docs/decisions#adr-32\\">ADR-32</a></li>\\n<li>부모 글을 읽을 수 있는 사람만, 자기 공감만 켜고 끔. 숨긴 댓글에는 못 누름. 차단한 사람의 공감은 숫자에서 뺌. 모두의 감사방에서도 같음</li>\\n<li>댓글 공감 알림은 보내지 않음. 계정을 삭제하면 다른 사람 댓글에 남긴 공감도 지움</li>\\n<li>배포: firestore(규칙 + 인덱스 <code>comments.reactions</code>) → 인덱스 &quot;사용 설정됨&quot; 확인 → 함수(<code>deleteAccount</code>) → Hosting, 앱은 iOS 1.0.1 (5)부터 → <a href=\\"/grato-docs/operations/deploy#comment-reactions\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-26","html":"<h3 id=\\"ad-check\\" tabindex=\\"-1\\">모두의 감사방 광고 검사 <a class=\\"header-anchor\\" href=\\"#ad-check\\" aria-label=\\"Permalink to &quot;모두의 감사방 광고 검사 {#ad-check}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>운영자 신고 화면에 <strong>광고 의심</strong> 탭(모두의 감사방 자동 검사가 올린 열린 신고 모아 보기). 카드에 &quot;광고 의심&quot;과 걸린 징후(&quot;링크 · 한글로 쓴 번호&quot; 등)를 보여 줌 → <a href=\\"/grato-docs/features/safety#ad-check\\">광고 검사</a></li>\\n<li>내용 필터에 돌려 쓴 연락처(한글로 쓴 번호, 메신저 ID 안내, 돌려 쓴 링크)를 찾는 <code>findContactSignals</code>. 질문 제안 필터는 그대로 → <a href=\\"/grato-docs/decisions#adr-30\\">ADR-30</a></li>\\n<li><strong>쓸 때 검사</strong>: 모두의 감사방 글·댓글에 링크·이메일·전화번호나 돌려 쓴 연락처가 있으면 서버가 운영자 대기열에 올림(사유 스팸·광고, 숨기지 않음, 작성자에게 알리지 않음, 원문 복사 없음). 대상의 첫 신고만 운영자 푸시. 일반 Circle·나만 보기는 그대로 → <a href=\\"/grato-docs/features/safety#ad-check-on-write\\">쓸 때 검사</a></li>\\n<li><strong>6시간 검사</strong>: 새 예약 함수 <code>scanOpenCircleAds</code>(KST 0·6·12·18시)가 지난 7시간의 모두의 감사방 글·댓글에서 빠진 글, 같은 링크·번호 반복, 갓 들어온 계정의 연락처, 몰아쓰기·댓글 도배를 찾아 대기열에 올리고 운영자에게 &quot;광고 의심 n건&quot; 한 번 알림 → <a href=\\"/grato-docs/features/safety#ad-check-scan\\">6시간 검사</a></li>\\n<li>사용자 화면은 바뀌지 않음. 규칙 변경 없음. 새 인덱스(<code>comments.createdAt</code> 컬렉션 그룹)와 새 함수 → functions + firestore + Hosting 배포 → <a href=\\"/grato-docs/operations/deploy#release-ad-check\\">배포 주의</a></li>\\n</ul>\\n"},{"id":"GRATO-35","html":"<h3 id=\\"season-themes\\" tabindex=\\"-1\\">겨울·신년 이미지 테마와 감사 글·배지·초대장 이미지 <a class=\\"header-anchor\\" href=\\"#season-themes\\" aria-label=\\"Permalink to &quot;겨울·신년 이미지 테마와 감사 글·배지·초대장 이미지 {#season-themes}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>배지에 <strong>이미지 테마</strong>(겨울·신년)를 달 수 있음(관리자 › 배지). 그 배지를 받은 사람만 캘린더·배지·감사 글·초대장 이미지를 그 테마로 그림. 받은 테마는 빼지 않고, 잠금·가격 표시 없음 → <a href=\\"/grato-docs/features/stats-badges#themes\\">이미지 테마</a>, <a href=\\"/grato-docs/decisions#adr-37\\">ADR-37</a></li>\\n<li>새 이미지: 감사 글(작성자가 글 상세에서), 받은 배지(배지 상세), Circle 초대장(Circle 설정 › 초대, 초대 코드는 이미지에 넣지 않고 함께 가는 메시지에만). 캘린더 저장도 미리보기 시트로 열림</li>\\n<li>캘린더 이미지(기본 테마)의 옅은 글자를 진하게: 월·요일·&quot;기록한 날&quot;·기록 안 한 날 숫자 회색 400·300 → 500, &quot;기록한 날&quot; 숫자 주황 500 → 700. 바탕 위 대비 AA(4.5:1)</li>\\n<li>1.0.1 (4) 이하 앱은 테마를 몰라 늘 기본 모습(캘린더만). 고르기는 웹과 iOS 1.0.1 (5) 앱부터</li>\\n<li>배포: 함수(<code>evaluateBadges</code>)·규칙(<code>badges.theme</code>) 먼저 → 웹 → 앱 iOS 1.0.1 (5). 배지에 테마를 다는 것은 그 뒤 → <a href=\\"/grato-docs/features/stats-badges#themes\\">이미지 테마</a></li>\\n</ul>\\n"},{"id":"GRATO-37","html":"<h3 id=\\"release-ios-1-0-1-5\\" tabindex=\\"-1\\">iOS 1.0.1 (5) 빌드 <a class=\\"header-anchor\\" href=\\"#release-ios-1-0-1-5\\" aria-label=\\"Permalink to &quot;iOS 1.0.1 (5) 빌드 {#release-ios-1-0-1-5}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>iOS 빌드 번호를 5로(앱·위젯 확장, 버전은 1.0.1 그대로). 1.0.1 (4) 대신 이 빌드를 심사에 냄</li>\\n<li>앱에 새로 들어가는 것: 배지 축하 카드와 다음 배지, 쉼표의 날·기록한 날, 오늘의 주제(모두의 감사방은 꺼 둔 채), 댓글 공감, 시즌 배지 표시와 시즌 질문(날짜로 켜짐), 가입 직후 쓰기로 한 때와 그때를 말하는 매일 알림, 첫 나눔 표시, 이미지 테마, 올해의 감사 돌아보기(12/1부터), 그리고 지금까지 웹에만 있던 변경(호칭·연속일, 저장, 공지 등)</li>\\n<li>Cloud Tasks 준비 → 규칙·인덱스 → 함수 → Hosting → <code>backfillActiveDays</code> → 앱 보관·업로드 → <a href=\\"/grato-docs/operations/deploy#release-ios-1-0-1-5\\">배포 순서</a></li>\\n</ul>\\n"},{"id":"GRATO-60","html":"<h3 id=\\"signup-sources\\" tabindex=\\"-1\\">가입 유입 경로 기록 (꺼 둠) <a class=\\"header-anchor\\" href=\\"#signup-sources\\" aria-label=\\"Permalink to &quot;가입 유입 경로 기록 (꺼 둠) {#signup-sources}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>웹에서 캠페인 링크(UTM)로 처음 들어온 기기에 그 표시를 30일 보관했다가, 그 기기에서 <strong>가입할 때 한 번</strong> <code>users.signupSource</code>로 남기고 지움. UTM 없이 초대 링크로 들어오면 <code>invite</code>. 가입하지 않은 방문자는 서버에 아무것도 남지 않고, 앱에서는 모으지 않음 → <a href=\\"/grato-docs/architecture/data-model#users\\">데이터 모델</a></li>\\n<li>규칙: 문서를 만들 때만, 정해진 키·형식만(<code>isValidSignupSource</code>). 그 뒤 추가·변경·삭제 거부 → <a href=\\"/grato-docs/architecture/security-rules\\">보안 규칙</a></li>\\n<li>관리자 지표에 <strong>유입 경로</strong> 표(최근 90일 가입: 가입, 7일 안 첫 글, 비율, 캠페인 펼치기). 기존 &quot;가입 경로 · 사용 기기&quot;는 &quot;가입·사용 기기&quot;로 이름을 바꿈 → <a href=\\"/grato-docs/operations/metrics#signup-sources\\">운영 지표</a></li>\\n<li><strong>꺼진 채 배포</strong>: 개인정보 처리방침 개정 시행일 전에는 기기에도 남기지 않음(<code>SIGNUP_SOURCE_FROM = null</code>). 시행일을 넣어 배포하면 그날 0시(KST)부터 켜짐 → <a href=\\"/grato-docs/operations/deploy#release-signup-sources\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-71","html":"<h3 id=\\"season-badges\\" tabindex=\\"-1\\">시즌 배지: 기간에 기록한 날, 받은 배지는 기간 뒤에도 <a class=\\"header-anchor\\" href=\\"#season-badges\\" aria-label=\\"Permalink to &quot;시즌 배지: 기간에 기록한 날, 받은 배지는 기간 뒤에도 {#season-badges}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>새 배지 조건 <strong>&quot;시즌 기간에 기록한 날&quot;</strong>(<code>season_days</code>): 배지 기간(KST) 안에 글을 쓴 날 수. 하루 쉬어도 떨어지지 않고, 기간 전 기록은 세지 않음. 관리자 › 배지에서 기간(KST 날짜)·시즌 키를 넣어 만들고, 문서 ID는 <code>season_days_{값}_{시즌 키}</code> → <a href=\\"/grato-docs/features/stats-badges#season-badges\\">시즌 배지</a></li>\\n<li>관리자 배지 화면에 기간 입력(시작일 00:00–마지막 날 23:59)이 생김. 다른 기간 한정 배지에도 씀</li>\\n<li>마이페이지 배지: <strong>받은 배지는 기간이 끝나도 보임</strong>(예전에는 기간이 지나면 받은 사람에게도 숨김). 받지 않은 배지만 기간 밖에서 숨김</li>\\n<li>배지 상세: 기간(&quot;기간 11월 15일–12월 31일&quot;), 시즌 배지는 &quot;시즌 기간에 기록한 날 7일&quot;과 &quot;이번 시즌에 n일 기록했어요&quot;(정보만)</li>\\n<li>개발 빌드에만 있는 <a href=\\"/grato-docs/mobile/#dev-clock\\">테스트 날짜</a>로 시즌 화면을 미리 봄. Hosting predeploy가 이 빌드를 막음</li>\\n<li>함수 + Hosting 배포, 앱은 iOS 1.0.1 (5)부터(1.0.1 (4) 이하는 조건 줄에 영문 키가 보이고, 기간이 끝나면 받은 시즌 배지가 목록에서 빠짐). 규칙·인덱스 변경 없음</li>\\n</ul>\\n"},{"id":"GRATO-72","html":"<h3 id=\\"season-questions\\" tabindex=\\"-1\\">연말연초 시즌 질문 <a class=\\"header-anchor\\" href=\\"#season-questions\\" aria-label=\\"Permalink to &quot;연말연초 시즌 질문 {#season-questions}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li><strong>오늘의 질문이 시즌판</strong>: 11/15–11/30 &quot;감사의 계절&quot;(8개를 두 번), 12/1–12/31 &quot;한 해 돌아보기&quot;(연말 21개 + 12/22부터 1–6번 다시 + 12/28–12/31 마무리 4개), 1/1–1/10 &quot;신년 감사&quot; 10개. 쓰기 화면 카드·홈 화면 위젯·카드뉴스가 같은 날 같은 질문(KST). 1/11부터 기본 순환 → <a href=\\"/grato-docs/features/guided-writing#season-questions\\">시즌 질문</a></li>\\n<li>감사의 계절·한 해 돌아보기 질문 뒤 이어지는 질문은 시즌 질문 3개 중 하나. &quot;다른 질문&quot;은 그대로 풀 전체. 기본은 나만 보기</li>\\n<li><strong>매일 알림 문구</strong>: 시즌 날에는 &quot;오늘의 감사의 계절 질문이 기다려요 🍂&quot; / &quot;오늘의 한 해 돌아보기 질문이 기다려요 ❄️&quot; / &quot;오늘의 신년 감사 질문이 기다려요 🌅&quot;(초안). 웹 푸시와 앱 로컬 알림이 같은 문구 데이터(<code>reminderCopy.json</code> 두 사본) → <a href=\\"/grato-docs/features/notifications#daily-reminder-copy\\">매일 알림 문구</a></li>\\n<li>운영: <code>seedSeasonQuestions</code>로 11/15(일) 07:00에 넣고 2/1에 숨김(<code>--dry-run</code>, 멱등, 운영자가 숨긴 질문은 그대로) → <a href=\\"/grato-docs/operations/deploy#season-questions\\">배포: 시즌 질문</a>. 카드뉴스는 시즌 날짜에 자동으로 시즌 질문</li>\\n<li>분석: <code>gratitude_started</code>(질문으로 쓰기)에 시즌 질문이면 <code>seasonKey</code></li>\\n<li>개발 빌드에만 있는 <a href=\\"/grato-docs/mobile/#dev-clock\\">테스트 날짜</a>로 11/15·12/1·12/28·1/1·2/1을 미리 봄</li>\\n<li>함수(<code>sendDailyReminder</code>) + Hosting 배포, 앱은 iOS 1.0.1 (5)부터(1.0.1 (4) 이하는 시드된 시즌 질문을 &quot;다른 질문&quot;·순환 풀에서 만남). 규칙·인덱스 변경 없음 → <a href=\\"/grato-docs/decisions#adr-35\\">ADR-35</a></li>\\n</ul>\\n"},{"id":"GRATO-73","html":"<h3 id=\\"year-review\\" tabindex=\\"-1\\">올해의 감사 돌아보기 카드 (마이페이지, 시즌 기간만) <a class=\\"header-anchor\\" href=\\"#year-review\\" aria-label=\\"Permalink to &quot;올해의 감사 돌아보기 카드 (마이페이지, 시즌 기간만) {#year-review}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>시즌 기간(기본 12/1–1/31 KST)에 마이페이지 맨 위에 &quot;{연도}년 돌아보기&quot; 카드: 올해 고마움을 적은 날, 달마다 점, 펼치면 처음 쓴 감사·다시 읽어 볼 감사 3개·돌아보는 질문으로 쓰기. 나만 보고, 비교·순위 없음. 계산은 기기 안에서 내 글로만 → <a href=\\"/grato-docs/features/stats-badges#year-review\\">올해의 감사 돌아보기</a></li>\\n<li>&quot;이미지로 간직하기&quot;: 4:5 이미지, 기본은 숫자 없음(&quot;기록한 날 넣기&quot;를 켜야 들어감), 감사 글 제목·내용은 넣지 않음. 받은 이미지 테마(겨울·신년 등)로 그릴 수 있음(다른 이미지와 같은 시트)</li>\\n<li>운영: <code>appConfig/yearReview</code>로 앱 업데이트 없이 끄거나 기간을 옮김(<code>setupYearReview</code> 스크립트). Firestore 규칙 배포 필요(앱·웹보다 먼저) → <a href=\\"/grato-docs/operations/deploy#year-review\\">켜고 끄기</a>, <a href=\\"/grato-docs/decisions#adr-38\\">ADR-38</a></li>\\n<li>개발 빌드에서만 🕒로 날짜를 옮겨 볼 수 있음. Hosting predeploy가 그런 빌드의 배포를 막음</li>\\n</ul>\\n"},{"id":"GRATO-76","html":"<h3 id=\\"first-share\\" tabindex=\\"-1\\">Circle 첫 나눔 알림 문구 <a class=\\"header-anchor\\" href=\\"#first-share\\" aria-label=\\"Permalink to &quot;Circle 첫 나눔 알림 문구 {#first-share}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>한 사람이 <strong>그 Circle에 처음</strong> 나눈 글이면 멤버가 받는 새 글 알림이 &quot;{이름}님이 Circle에 처음 감사를 나눴어요 🌱&quot;(이름이 없으면 &quot;새 멤버가 …&quot;)로 바뀜. 받는 사람·설정·횟수는 그대로(알림이 늘지 않음), 모두의 감사방·자동 숨김된 글은 대상 아님 → <a href=\\"/grato-docs/features/notifications#first-share\\">첫 나눔 알림</a></li>\\n<li>서버 전용 표시 문서 <code>circleFirstShares/{groupId}_{uid}</code>(규칙 match 없음). 예전부터 그 Circle에 쓴 사람은 <code>legacy</code> 표시만 남고 문구는 그대로. 계정 삭제·Circle 삭제 때 함께 지움 → <a href=\\"/grato-docs/architecture/data-model#circle-first-shares\\">데이터 모델</a></li>\\n<li>알림 data에 <code>variant: &quot;first&quot;</code>(<code>type: circle_post</code> 그대로, 클릭 경로 같음). <code>notification_clicked</code> 이벤트에 <code>variant</code>를 담음(웹 포그라운드·앱 — 앱은 iOS 1.0.1 (5)부터)</li>\\n<li>함수 배포만 필요(규칙·인덱스 변경 없음, 앱 업데이트 없이 동작). 웹 클릭 이벤트는 Hosting 배포 때</li>\\n</ul>\\n"},{"id":"GRATO-77","html":"<h3 id=\\"first-share-followup\\" tabindex=\\"-1\\">첫 나눔에 24시간 반응이 없으면 리더에게 한 번 <a class=\\"header-anchor\\" href=\\"#first-share-followup\\" aria-label=\\"Permalink to &quot;첫 나눔에 24시간 반응이 없으면 리더에게 한 번 {#first-share-followup}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>Circle 첫 나눔에 24시간 동안 다른 사람의 공감·댓글이 없으면 그 Circle <strong>리더에게만 한 번</strong> &quot;{이름}님이 처음 나눈 감사가 있어요 / {글 제목} · 공감이나 댓글로 반겨 줄 수 있어요&quot;. 밤(KST 22:00–08:59)이면 다음 09:00, 리더당 하루 1회, 리더의 Circle 새 글 알림 설정을 따름. 쓰는 사람에게는 아무것도 가지 않음 → <a href=\\"/grato-docs/features/notifications#first-share-followup\\">리더 알림</a></li>\\n<li>새 작업 큐 함수 <code>firstShareFollowup</code>(Cloud Tasks, 글마다 작업 하나). 결과는 첫 나눔 표시 문서의 <code>followupAt</code>·<code>followupSent</code>·<code>followupSkipped</code> → <a href=\\"/grato-docs/decisions#adr-33\\">ADR-33</a></li>\\n<li>함수 배포만(앱 업데이트 없이 동작). <strong>처음 한 번 Cloud Tasks API·IAM 역할 설정 필요</strong>(CI 배포 계정에 <code>roles/cloudtasks.queueAdmin</code>) → <a href=\\"/grato-docs/operations/deploy#cloud-tasks\\">배포: Cloud Tasks</a>. 로컬 에뮬레이터에 <code>tasks</code> 추가</li>\\n</ul>\\n"},{"id":"GRATO-78","html":"<h3 id=\\"first-share-metrics\\" tabindex=\\"-1\\">관리자 지표 &quot;첫 나눔&quot; 칸 <a class=\\"header-anchor\\" href=\\"#first-share-metrics\\" aria-label=\\"Permalink to &quot;관리자 지표 &quot;첫 나눔&quot; 칸 {#first-share-metrics}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>관리자 분석 화면의 지표에 <strong>첫 나눔 · 최근 4주</strong>: 7일 안에 다시 나눔(주 지표), 24시간 안 첫 반응, 첫 반응까지 시간 중앙값, 리더 알림 보냄·건너뜀(이유별)·보낸 뒤 24시간 반응, Circle 새 글 알림 끈 사람(감시), 출시 전 4주 다시 나눔(비교 기준) → <a href=\\"/grato-docs/operations/metrics#first-shares\\">지표: 첫 나눔</a></li>\\n<li>공감·댓글 트리거가 만든 지 72시간 안의 첫 나눔에 첫 반응 시각(<code>firstResponseAt</code>·<code>firstResponseType</code>)을 한 번 기록</li>\\n<li>함수 + Hosting 배포(규칙·인덱스 변경 없음). 사용자에게 보이는 숫자는 없음</li>\\n</ul>\\n"},{"id":"GRATO-79","html":"<h3 id=\\"first-share-ui\\" tabindex=\\"-1\\">첫 나눔 화면 표시 <a class=\\"header-anchor\\" href=\\"#first-share-ui\\" aria-label=\\"Permalink to &quot;첫 나눔 화면 표시 {#first-share-ui}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>Circle에 처음 나눈 글: 저장 직후 그 Circle 피드 위에 <strong>&quot;Circle 멤버에게 알렸어요&quot;</strong>(5초, 이 기기의 피드로 추측, 숫자 없음), Circle 피드 카드에 7일 동안 <strong>&quot;처음 나눈 감사&quot;</strong> → <a href=\\"/grato-docs/features/circles#first-share\\">첫 나눔</a></li>\\n<li>서버가 첫 나눔 글에 <code>firstShare: true</code>를 씀(클라이언트 쓰기 거부, 규칙 테스트 추가). 모두의 감사방·내 기록·저장한 감사에는 표시 없음</li>\\n<li>함수 + Hosting 배포(규칙 파일 변경 없음 — 기존 생성·수정 규칙이 이미 막음). 앱은 iOS 1.0.1 (5)부터</li>\\n</ul>\\n"},{"id":"GRATO-80","html":"<h3 id=\\"pr-checks\\" tabindex=\\"-1\\">PR마다 테스트 자동 실행, 변경 이력은 PR별 파일로 <a class=\\"header-anchor\\" href=\\"#pr-checks\\" aria-label=\\"Permalink to &quot;PR마다 테스트 자동 실행, 변경 이력은 PR별 파일로 {#pr-checks}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>PR과 <code>main</code> push마다 GitHub Actions <strong>Test</strong> 워크플로가 클라이언트·함수 단위·보안 규칙·함수 엔드투엔드·웹 빌드·문서 빌드를 나란히 돌림. 바뀐 경로만 돌고, 마지막 <strong>Test summary</strong>가 하나로 묶음(필수 검사로 지정 가능). 비밀값·Google 자격 증명 없음 → <a href=\\"/grato-docs/operations/testing#ci\\">CI 테스트</a></li>\\n<li>변경 이력은 이제 PR마다 <code>docs/changelog/unreleased/&lt;티켓&gt;.md</code>에 쓰고, 배포할 때 <code>npm run changelog</code>로 합침. 열린 PR끼리 <code>changelog.md</code> 맨 위에서 충돌하지 않음 → <a href=\\"/grato-docs/decisions#adr-36\\">ADR-36</a>, <a href=\\"/grato-docs/contributing-docs#changelog\\">변경 이력 쓰기</a></li>\\n<li>앱·서버 동작 변경 없음(배포할 것 없음)</li>\\n</ul>\\n"},{"id":"GRATO-81","html":"<h3 id=\\"writing-plan\\" tabindex=\\"-1\\">가입 직후 &quot;언제 감사를 떠올릴까요?&quot; <a class=\\"header-anchor\\" href=\\"#writing-plan\\" aria-label=\\"Permalink to &quot;가입 직후 &quot;언제 감사를 떠올릴까요?&quot; {#writing-plan}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>새 계정은 동의를 마친 뒤 한 화면에서 감사를 떠올릴 때를 고름: 아침 차 한 잔 할 때 · 출근·등교길 · 점심 먹고 나서 · 퇴근·하교길 · 잠들기 전 · 내가 정한 때(시각은 15분 단위로 바꿈). 고르면 &quot;잠들기 전이 되면, 고마웠던 일을 한 줄 적어요.&quot; 같은 계획 문장 → <a href=\\"/grato-docs/features/account#writing-plan\\">가입 직후</a></li>\\n<li>고른 때가 매일 감사 알림 시각이 됨. <strong>이 시간에 알려 주세요</strong>를 누를 때만 알림 권한을 묻고, <strong>알림 없이 정해 둘게요</strong>·<strong>건너뛰기</strong>도 있음. 권한을 거부하거나 알림이 안 되는 브라우저여도 계획은 저장</li>\\n<li>초대 링크로 가입한 사람과 이미 가입한 사람(계획 없음)은 홈에 카드가 한 번 보임. 마이페이지 &gt; 설정에 <strong>쓰기로 한 때</strong> 줄(바꾸기)</li>\\n<li><code>users.writingPlan</code> 추가, 규칙이 모양을 검사 → <a href=\\"/grato-docs/architecture/security-rules#writing-plan\\">보안 규칙</a>. 배포: 규칙 → Hosting → 앱(iOS 1.0.1 (5)). 함수 변경 없음</li>\\n</ul>\\n"},{"id":"GRATO-82","html":"<h3 id=\\"daily-reminder-cue\\" tabindex=\\"-1\\">매일 알림이 고른 때를 말함 <a class=\\"header-anchor\\" href=\\"#daily-reminder-cue\\" aria-label=\\"Permalink to &quot;매일 알림이 고른 때를 말함 {#daily-reminder-cue}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>쓰기로 한 때를 골랐으면 매일 알림 제목이 그 때를 말함: &quot;잠들기 전, 오늘의 감사 한 줄 🌙&quot;, &quot;점심 뒤 잠깐, 오늘의 감사 한 줄 🍚&quot; 등. &quot;내가 정한 때&quot;·계획 없음·알림 시각을 따로 바꾼 경우는 예전 문구 → <a href=\\"/grato-docs/features/notifications#daily-reminder-copy\\">매일 알림 문구</a></li>\\n<li>웹 푸시와 앱 휴대폰 알림이 같은 문구 파일(<code>reminderCopy.json</code>)을 씀. 시즌 문구가 들어오면 시즌 문구 앞에 때 단서를 붙임</li>\\n<li>알림 횟수·조건은 그대로. 알림을 누르면 <code>notification_clicked</code>에 <code>cue</code></li>\\n<li>배포: 함수(<code>sendDailyReminder</code>) → 앱(iOS 1.0.1 (5), 휴대폰 알림 문구). 규칙·인덱스 변경 없음</li>\\n</ul>\\n"},{"id":"GRATO-83","html":"<h3 id=\\"metrics-writing-plan\\" tabindex=\\"-1\\">관리자 지표: 가입 7일 안 3일 기록 <a class=\\"header-anchor\\" href=\\"#metrics-writing-plan\\" aria-label=\\"Permalink to &quot;관리자 지표: 가입 7일 안 3일 기록 {#metrics-writing-plan}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>관리자 지표에 <strong>가입 7일 안 3일 기록</strong> 비율: 최근 8주 가입 주별로 전체와 그룹(계획 · 알림 켬 / 알림 없이, 건너뜀, 보고 나감, 안 봄), <strong>기능 전 4주 ↔ 기능 뒤</strong> 비교, 계획 세운 비율 → <a href=\\"/grato-docs/operations/metrics#writing-plan\\">가입 7일 안 3일</a></li>\\n<li>쓰기로 한 때별 계획 수·알림 켬·최근 28일 매일 알림 누름(사람·일당 근사값)</li>\\n<li>그룹은 스스로 고른 사람이라 치우친다는 안내를 화면에 한 줄. 운영자 제외, 사람별 값 없음</li>\\n<li>함수(<code>adminMetrics</code>) + Hosting 배포. 새 인덱스 없음(오늘 현황의 <code>analyticsEvents (event, createdAt)</code> 사용), 규칙 변경 없음</li>\\n</ul>\\n"},{"id":"GRATO-94-android","html":"<h3 id=\\"android-release-workflow\\" tabindex=\\"-1\\">Android 빌드를 GitHub Actions로 Play 내부 테스트까지 <a class=\\"header-anchor\\" href=\\"#android-release-workflow\\" aria-label=\\"Permalink to &quot;Android 빌드를 GitHub Actions로 Play 내부 테스트까지 {#android-release-workflow}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>Actions의 <strong>Android release</strong>를 손으로 시작하면 오너 승인 뒤 웹 빌드·<code>cap sync android</code>·AAB 빌드(업로드 키 서명)를 하고, AAB를 아티팩트로 남긴 뒤 Play 내부 테스트(또는 비공개 테스트) 트랙에 올립니다. 프로덕션 트랙·심사·스토어 문구는 건드리지 않습니다 → <a href=\\"/grato-docs/operations/ci-mobile#android\\">앱 빌드 CI</a></li>\\n<li><code>versionCode</code>는 입력값 또는 실행 번호 + 오프셋(기본 5)이고, 커밋된 값보다 커야 합니다 → <a href=\\"/grato-docs/operations/ci-mobile#versions\\">버전 번호</a></li>\\n<li><code>android/app/build.gradle</code>은 <code>keystore.properties</code>가 없을 때 환경 변수로도 업로드 키를 읽습니다(맥에서의 빌드는 그대로).</li>\\n</ul>\\n"},{"id":"GRATO-94-ios","html":"<h3 id=\\"ios-xcode-cloud\\" tabindex=\\"-1\\">iOS 빌드를 Xcode Cloud로, 버전 번호 한 번에 바꾸기 <a class=\\"header-anchor\\" href=\\"#ios-xcode-cloud\\" aria-label=\\"Permalink to &quot;iOS 빌드를 Xcode Cloud로, 버전 번호 한 번에 바꾸기 {#ios-xcode-cloud}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>Xcode Cloud가 저장소의 <code>ios/App/ci_scripts/</code>로 웹 빌드·<code>cap sync ios</code>를 하고, 앱·위젯 빌드 번호를 Xcode Cloud 번호로 맞춰 TestFlight 내부 테스트까지 올립니다. 시작은 손으로 또는 <code>release/ios-*</code> 태그, 심사 제출은 오너가 손으로 → <a href=\\"/grato-docs/operations/ci-mobile#ios\\">앱 빌드 CI</a></li>\\n<li><code>npm run version:bump -- --version 1.0.2 --build 6</code>: iOS 앱·위젯과 Android의 버전·빌드 번호를 한 번에 바꿉니다(빌드 번호는 올라가기만) → <a href=\\"/grato-docs/operations/ci-mobile#versions\\">버전 번호</a></li>\\n<li>Xcode Cloud가 쓰도록 scheme <code>App</code>을 공유 scheme으로 커밋했습니다.</li>\\n</ul>\\n"},{"id":"GRATO-94-preview","html":"<h3 id=\\"pr-web-preview\\" tabindex=\\"-1\\">PR 웹 미리보기 <a class=\\"header-anchor\\" href=\\"#pr-web-preview\\" aria-label=\\"Permalink to &quot;PR 웹 미리보기 {#pr-web-preview}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>같은 저장소 PR에서 테스트가 통과하면 그 PR의 웹 화면을 Firebase Hosting 미리보기 주소(<code>pr-&lt;번호&gt;</code>, 7일 뒤 사라짐)에 올리고 PR에 링크 댓글을 답니다. 운영 사이트(grato.today)에는 올리지 않습니다. 미리보기는 운영 데이터에 붙으므로 테스트 계정으로만 확인합니다 → <a href=\\"/grato-docs/operations/deploy#ci-preview\\">PR 웹 미리보기</a></li>\\n<li>오너 설정(Environment <code>preview</code>, 미리보기 전용 WIF 풀·서비스 계정, 저장소 수준 웹 설정 값)을 마친 뒤부터 동작합니다 → <a href=\\"/grato-docs/decisions#adr-39\\">ADR-39</a></li>\\n</ul>\\n"},{"id":"GRATO-103","html":"<h3 id=\\"environments-stg\\" tabindex=\\"-1\\">테스트용 stg 환경과 PR 미리보기 분리 <a class=\\"header-anchor\\" href=\\"#environments-stg\\" aria-label=\\"Permalink to &quot;테스트용 stg 환경과 PR 미리보기 분리 {#environments-stg}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>개발자 환경을 dev(로컬 에뮬레이터) · stg(별도 Firebase 프로젝트 <code>grato-stg</code>) · prod로 나눔. 사용자에게 보이는 변화는 없음</li>\\n<li>PR 웹 미리보기가 운영 데이터 대신 stg에 붙음. 배포 워크플로는 <code>target-env</code>(기본 stg)로 대상을 고르고 운영은 <code>main</code>에서만</li>\\n<li>시드·백필·설정 스크립트는 대상 프로젝트를 검사하고, 운영에는 <code>GRATO_CONFIRM_PROJECT=grato-44d47</code>을 함께 줘야 돎</li>\\n<li>오너 설정(요금제·API·로그인·WIF·GitHub 변수)이 끝나기 전에는 Preview 워크플로가 실패할 수 있음 → <a href=\\"/grato-docs/operations/deploy#environments\\">환경</a>, <a href=\\"/grato-docs/decisions#adr-40\\">ADR-40</a></li>\\n</ul>\\n"}]'),d={key:0},u=["innerHTML"],f=JSON.parse('{"title":"변경 이력","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1792220032000}'),h={name:"changelog.md"},m=Object.assign(h,{setup(q){return(g,e)=>(o(),a("div",null,[e[0]||(e[0]=r("",4)),t(l).length?s("",!0):(o(),a("p",d,"없음")),(o(!0),a(c,null,n(t(l),i=>(o(),a("div",{key:i.id,class:"unreleased-entry",innerHTML:i.html},null,8,u))),128)),e[1]||(e[1]=r("",126))]))}});export{f as __pageData,m as default};
